mapper.select:
select sum(a.pCalculateRoughlyAmount) as pCalculateRoughlyAmountSum, sum(a.pEstimateAmount) as pEstimateAmountSum, sum(a.pApproveBudget) as pApproveBudgetSum, sum(a.pFinalAccounts) as pFinalAccountsSum, sum(a.secMoneyTotal) as secMoneyTotalSum, sum(a.conMoneyTotal) as conMoneyTotalSum, sum(a.conPayApprovalTotal) as conPayApprovalTotalSum, sum(a.conPayYearTotal) as conPayYearTotalSum, sum(a.unPayAmtTotal) as unPayAmtTotalSum, sum(a.proPayApprovalTotal) as proPayApprovalTotalSum, sum(a.saApprovedAmtTotal) as saApprovedAmtTotalSum from ( select mn.P_Calculate_Roughly_Amount as pCalculateRoughlyAmount, mn.P_Estimate_Amount as pEstimateAmount, mn.P_Approve_Budget as pApproveBudget, mn.P_Final_Accounts as pFinalAccounts, (select sum(sec.Sec_Money) from sec_info sec left join Sec_Project sp on sp.Sec_Id=sec.Sec_Id where sec.Sec_Flow_State=7 and sp.P_ID=mn.P_ID) as secMoneyTotal, (select sum(cc.Con_Money_Total) from Con_Contract cc where cc.Con_Project_Id=mn.P_ID and cc.Con_Approval_State=7) as conMoneyTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01') as conPayApprovalTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01'
) as conPayYearTotal, (select sum(pay.Pay_Payable-pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01') as unPayAmtTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is null and pay.Pay_State=7 and pay.Pay_Category='02') as proPayApprovalTotal, (select sum(sam.Sa_Approved_Amt) from Inv_Settlement_Apply sam where sam.P_Id=mn.P_Id and sam.Sa_State=7) as saApprovedAmtTotal from Pre_Project mn left join SYS_Company c2 on c2.C_Id=mn.P_Construction_Unit left join SYS_Company c11 on c11.C_Id=mn.P_Use_Unit ${params.authSql}
) a

select mn.P_Id as pId, mn.P_Name as pName, mn.P_Code as pCode, mn.P_Use_Unit as pUseUnit, ifnull(c11.C_Name, mn.P_Use_Unit) as pUseUnitName, mn.P_Construction_Unit as pConstructionUnit, mn.P_Calculate_Roughly_Amount as pCalculateRoughlyAmount, mn.P_Estimate_Amount as pEstimateAmount, mn.P_Approve_Budget as pApproveBudget, mn.P_Final_Accounts as pFinalAccounts, mn.P_Project_Stage as pProjectStage, mn.P_PLan_Start_Date as pPLanStartDate, mn.P_Plan_Complete_Date as pPlanCompleteDate, mn.P_Project_Status as pProjectStatus, mn.P_Parent_ID as pParentId, c2.C_Name as pConstructionUnitName, (select sum(sec.Sec_Money) from sec_info sec left join Sec_Project sp on sp.Sec_Id=sec.Sec_Id where sec.Sec_Flow_State=7 and sp.P_ID=mn.P_ID) as secMoneyTotal, (select sum(cc.Con_Money_Total) from Con_Contract cc where cc.Con_Project_Id=mn.P_ID and cc.Con_Approval_State=7) as conMoneyTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01') as conPayApprovalTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01'
) as conPayYearTotal, (select sum(pay.Pay_Payable-pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is not null and pay.Pay_State=7 and pay.Pay_Category='01') as unPayAmtTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.P_Id=mn.P_Id and pay.Con_Id is null and pay.Pay_State=7 and pay.Pay_Category='02') as proPayApprovalTotal, (select sum(sam.Sa_Approved_Amt) from Inv_Settlement_Apply sam where sam.P_Id=mn.P_Id and sam.Sa_State=7) as saApprovedAmtTotal from Pre_Project mn left join SYS_Company c2 on c2.C_Id=mn.P_Construction_Unit left join SYS_Company c11 on c11.C_Id=mn.P_Use_Unit ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time desc

select mn.P_Id
from Pre_Project mn ${authSql}

    and mn.Te_Id=#{teId}

select P_ID as pId, P_Name as pName, P_Overview as pOverview,
P_Imp_State as pImpState, P_Is_Project_Approval as pIsProjectApproval, P_Type as pType, P_Inv_Total as pInvTotal, P_Inv_Caliber as pInvCaliber, P_PLan_Start_Date as pPLanStartDate, P_Plan_Complete_Date as pPlanCompleteDate, P_Build_Model as pBuildModel, P_Imp_Company as pImpCompany, d.D_Name as pDepartmentName, P_Use_Unit as pUseUnit from Pre_Project mn left join SYS_Department d on mn.P_Competent_Department=d.D_Id where mn.deleted=false and State=7 and mn.P_Id in ( select P_Id from Oa_Annual_Plan_Dtl apd left join Oa_Annual_Plan ap on ap.id=apd.Ap_Id where ap.Ap_Year=#{year} )
order by ${sortFiled} ${sortType}
limit #{start},#{size}

mapper.sql:
from Pre_Project mn
left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit
left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit
left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit
left join SYS_Department d on mn.P_Competent_Department=d.D_Id
left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID

    ${authSql}


    and mn.Te_Id = #{params.teId}


    and mn.P_Type = #{params.pType}


    and (mn.State = #{params.state} or (mn.ppr_id is not null and mn.State != 3))


    and mn.P_Category = #{params.pCategory}


    and mn.P_Status = #{params.pStatus}


    and mn.P_Region like concat('%',#{params.pRegion},'%')


    and mn.P_Project_Stage = #{params.pProjectStage}


    and mn.P_Construction_Unit = #{params.pConstructionUnit}


    and mn.P_Competent_Department = #{params.pCompetentDepartment}


    and mn.P_Name like concat('%',#{params.pName},'%')


    and mn.P_Apply_Name like concat('%',#{params.pApplyName},'%')


    and mn.data_source_type = #{params.dataSourceType}


and mn.deleted=#{deleted}

mapper.select:
select distinct mn.P_Parent_ID

and mn.P_Parent_ID in
#{id}

sql.if:
and exists (select 1 from Con_Contract where Con_Project_Id=mn.P_Id

    and Con_Category=#{params.conCategory}


    and Con_Type=#{params.conType} and Con_Approval_State=7

)

mapper.sql:
select ranked.P_Id, count(*) as archive_count
from (
select project_files.*,
max(project_files.rank_key) over (
partition by project_files.P_Id, project_files.file_md5
) as max_key
from (
select ar.P_Id, ar.Ap_State, af.Af_State,
annex.File_MD5_Code as file_md5,

    

as rank_key
from Archive ar
inner join Archive_File af on af.Ap_Id = ar.Ap_Id
left join SYS_FileAnnex annex on annex.file_id = af.Af_Annex_Id
where ar.P_Id in (

)
) project_files
) ranked
where ranked.Ap_State = 1 and ranked.Af_State = 1
and (ranked.file_md5 is null or ranked.rank_key = ranked.max_key)
group by ranked.P_Id

mapper.select:
select COUNT(*) as contractSum, SUM(Con_Money_Total) as conMoneyTotalSum from Con_Contract conf ${params.conAuthSql} and conf.Con_Approval_State=7
and conf.Con_Category=#{params.conCategory}
and conf.Con_Project_Id in (select mn.P_ID from Pre_Project mn
${params.authSql} and mn.deleted = false
and mn.state!=3 and mn.state!=0
)

select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c4.C_Name as pAuditUnitName, c5.C_Name as pCostUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, d2.D_Name as pDepartmentName, parent.P_Name as pParentName, parent.P_Name_History as pParentNameHistory, parent.P_code as pParentCode, mn.p_Category as pCategory, us1.U_Name as pProjectManagerName, us2.U_Name as pProjectLeaderName, us3.U_Name as pEngineerName, us4.U_Name as pEngineerLeaderName,
ifnull(ac.archive_count, 0) as archiveFileSum,
(select afa.Fa_Type from Archive_Filing_Apply afa where afa.P_Id=mn.P_Id and afa.Fa_State=7 order by afa.Fa_State_Time desc limit 1) as faType, ifnull(c11.C_Name, mn.P_Use_Unit) as pUseUnitName,
from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Company c4 on c4.C_Id=mn.P_Audit_Unit left join SYS_Company c5 on c5.C_Id=mn.P_Cost_Unit left join SYS_Company c11 on c11.C_Id=mn.P_Use_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join SYS_Department d2 on mn.P_Department = d2.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID left join Sys_User us1 on us1.U_Id=mn.P_Project_Manager left join Sys_User us2 on us2.U_Id=mn.P_Project_Leader left join Sys_User us3 on us3.U_Id=mn.P_Engineer left join Sys_User us4 on us4.U_Id=mn.P_Engineer_Leader
left join (
) ac on ac.P_Id = mn.P_Id
${params.authSql} and mn.deleted = false
order by archiveFileSum ${params.sortType}
order by d.D_Name ${params.sortType}
order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC
limit #{params.start},#{params.size}

select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c4.C_Name as pAuditUnitName, c5.C_Name as pCostUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name as pParentName, parent.P_Name_History as pParentNameHistory, parent.P_code as pParentCode, mn.p_Category as pCategory,
ifnull(ac.archive_count, 0) as archiveFileSum,
(select afa.Fa_Type from Archive_Filing_Apply afa where afa.P_Id=mn.P_Id and afa.Fa_State=7 order by afa.Fa_State_Time desc limit 1) as faType, , ifnull(c11.C_Name, mn.P_Use_Unit) as pUseUnitName from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Company c4 on c4.C_Id=mn.P_Audit_Unit left join SYS_Company c5 on c5.C_Id=mn.P_Cost_Unit left join SYS_Company c11 on c11.C_Id=mn.P_Use_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID
left join ( select ar.P_Id, count(*) as archive_count from Archive_File af left join Archive ar on af.Ap_Id = ar.Ap_Id left join SYS_FileAnnex sfa on sfa.file_id = af.Af_Annex_Id
where ar.Ap_State = 1 and af.Af_State = 1 and (sfa.File_MD5_Code is null or latest_md5.max_key is not null) group by ar.P_Id ) ac on ac.P_Id = mn.P_Id
${params.authSql} and mn.deleted = false
order by archiveFileSum ${params.sortType}
order by d.D_Name ${params.sortType}
order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC

select conf.Con_Project_Id as pId, count(*) as conNumTotal, SUM(Con_Money_Total) as conMoneyTotalSum from Con_Contract conf ${params.conAuthSql} and conf.Con_Approval_State!=3 and conf.Con_Approval_State!=0
and conf.Con_Category=#{params.conCategory}
and conf.Con_Project_Id in
#{id}
group by conf.Con_Project_Id

sql.if:
and mn.P_Id in (select Con_Project_Id from Con_Contract where Con_Approval_State=7 and Con_Type in
#{tp}
)

and mn.P_Id in (select cp.P_Id from Project_Cp cp left join Project_Cp_Dtl cpd on cp.Cp_Id=cpd.Cp_Id
where cp.State=7 and cpd.Cpd_State=7 and cpd.Cpd_Status=1 and cpd.Cpd_Code in
#{cpdCode}
)

and mn.P_Id in (select apd.P_Id from Oa_Annual_Plan_Dtl apd left join Oa_Annual_Plan ap on ap.id=apd.Ap_Id
where ap.State=7

    and Ap_Year=#{params.apYear}

)

mapper.select:
select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name_History as pParentNameHistory, parent.P_Name as pParentName, mn.P_Imp_Company as pImpCompany, pmu.u_name as pProjectManagerName, mn.p_Category as pCategory,
from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID left join Sys_user pmu on mn.p_Project_Manager=pmu.u_id
${params.authSql}
WHERE 1=1
and mn.deleted = false
limit #{params.start},#{params.size}

select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name_History as pParentNameHistory, parent.P_Name as pParentName, mn.P_Imp_Company as pImpCompany, ipv.Ipv_P_Type, (select u.U_Name as managerName from SYS_User u left join SYS_Position_User_P pu on u.U_ID=pu.U_ID left join SYS_Position_P p on pu.PP_ID=p.PP_ID left join SYS_Department_P d on d.PD_ID=p.PD_ID WHERE d.P_Id = mn.p_id AND p.PP_Name = '项目经理' limit 1) as managerName,
from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID Left join Inv_Plan_Year ipv ON mn.p_id = ipv.p_id and ipv.Ipv_Declare_Year =#{params.icmReportingYear} and Ipv_State != 1
${params.authSql}
WHERE 1=1
and mn.deleted = false
and mn.P_Competent_Department IN
#{item}
and mn.P_Id IN (SELECT ipy.P_Id FROM Inv_Plan_Year ipy WHERE ipy.Ipv_Declare_Year = #{params.icmReportingYear} and ipy.ipv_state = 7
and ipy.Ipv_P_Type IN
#{item}
) AND mn.P_Id NOT IN (SELECT icm.P_Id FROM Inv_Complete_Month icm WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth} and icm.Icm_Reporting_Year = #{params.icmReportingYear})
OR mn.P_Id IN (SELECT icm.P_Id FROM Inv_Complete_Month icm left join Inv_Plan_Year ipyr on icm.Ipv_Id = ipyr.Ipv_Id WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth} and icm.Icm_Reporting_Year = #{params.icmReportingYear} and icm.transfer_status not in
#{item}
and ipyr.Ipv_P_Type IN
#{item}
)
and mn.P_Id IN (SELECT icm.P_Id FROM Inv_Complete_Month icm WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth} and icm.Icm_Reporting_Year = #{params.icmReportingYear}
and icm.plan_complete_result IN
#{item}
and icm.complete_result IN
#{item}
and icm.month_cumulative_inv_proportion < #{params.monthCumulativeInvProportion}
)
limit #{params.start},#{params.size}

        select
        count(1)
        from Pre_Project mn
        left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit
        left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit
        left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit
        left join SYS_Department d on mn.P_Competent_Department=d.D_Id
        left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID
        
            ${params.authSql}
        
        
            WHERE 1=1
        
        and mn.deleted = false
        
            and mn.P_Competent_Department IN
            
                #{item}
            
        
        
        
            and mn.P_Id IN (SELECT ipy.P_Id FROM Inv_Plan_Year ipy WHERE ipy.Ipv_Declare_Year = #{params.icmReportingYear}
            and ipy.ipv_state = 7
            
                and ipy.Ipv_P_Type IN
                
                    #{item}
                
            
            )
            AND mn.P_Id NOT IN (SELECT icm.P_Id FROM Inv_Complete_Month icm
            WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth}
            and icm.Icm_Reporting_Year = #{params.icmReportingYear})

            
                OR mn.P_Id IN (SELECT icm.P_Id FROM Inv_Complete_Month icm left join Inv_Plan_Year ipyr on icm.Ipv_Id = ipyr.Ipv_Id
                WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth}
                and icm.Icm_Reporting_Year = #{params.icmReportingYear}
                and icm.transfer_status not in
                
                    #{item}
                
                
                    and ipyr.Ipv_P_Type IN
                    
                        #{item}
                    
                
                )
            

        
        
            and mn.P_Id IN (SELECT icm.P_Id FROM Inv_Complete_Month icm
            WHERE icm.Icm_Reporting_Month = #{params.icmReportingMonth}
            and icm.Icm_Reporting_Year = #{params.icmReportingYear}
            
                and icm.plan_complete_result IN
                
                    #{item}
                
            
            
                and icm.complete_result IN
                
                    #{item}
                
            
            
                and icm.month_cumulative_inv_proportion < #{params.monthCumulativeInvProportion}
            
            )

select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, c4.c_Name as pUseUnitName, d.D_Name as pCompetentDepartmentName, parent.P_Name_History as pParentNameHistory, parent.P_Name as pParentName, mn.p_Project_Director_Tel as pProjectDirectorTel,
from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Company c4 on c4.C_Id=mn.P_Use_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID where mn.deleted = false
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC
limit #{params.start},#{params.size}

select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name_History as pParentNameHistory, parent.P_Name as pParentName,
from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID where mn.deleted = false
and mn.P_Competent_Department in
#{depId}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC

select (select count(1) from Qs_Record where Qsr_Category = 0 and Te_Id = #{teId} and Qsr_Rectify_Require_Time < now() and (Qsr_State != 7 and Qsr_State != 3)) as qualityOverdue, (select count(1) from Qs_Record where Qsr_Category = 0 and Te_Id = #{teId} and Qsr_Rectify_Require_Time < now() and (Qsr_State != 7 and Qsr_State != 3) and DateDiff(month, Qsr_Create_Time, getdate()) = 0) as qualityOverdueMonth, (select count(1) from Qs_Record where Qsr_Category = 0 and Te_Id = #{teId}
and DateDiff(dd, Qsr_Time, getdate()) = 0
and DateDiff(dd, Qsr_Create_Time, getdate()) = 0
) as qualityToday, (select count(1) from Qs_Record where Qsr_Category = 0 and Te_Id = #{teId} and DateDiff(month,
Qsr_Time Qsr_Create_Time , getdate()) = 0) as qualityTodayMonth, (select count(1) from Qs_Record where Qsr_Category = 1 and Te_Id = #{teId} and Qsr_Rectify_Require_Time < now() and (Qsr_State != 7 and Qsr_State != 3)) as securityOverdue, (select count(1) from Qs_Record where Qsr_Category = 1 and Te_Id = #{teId} and Qsr_Rectify_Require_Time < now() and (Qsr_State != 7 and Qsr_State != 3) and DateDiff(month, Qsr_Create_Time, getdate()) = 0) as securityOverdueMonth, (select count(1) from Qs_Record where Qsr_Category = 1 and Te_Id = #{teId}
and DateDiff(dd, Qsr_Time, getdate()) = 0
and DateDiff(dd, Qsr_Create_Time, getdate()) = 0
) as securityToday, (select count(1) from Qs_Record where Qsr_Category = 1 and Te_Id = #{teId} and DateDiff(month,
