select c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as pAgentUnitNameHistory, c3.C_Name_History as pDesignUnitNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c4.C_Name as pAuditUnitName, c5.C_Name as pCostUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name as pParentName, parent.P_Name_History as pParentNameHistory, parent.P_code as pParentCode,
ifnull(ac.archive_count, 0) as archiveFileSum,
(select afa.Fa_Type from Archive_Filing_Apply afa where afa.P_Id=mn.P_Id and afa.Fa_State=7 order by afa.Fa_State_Time desc limit 1) as faType, mn. p_Department as pDepartment, , case when (mn.State !=3 and mn.State != 7 and mn.ppr_id is not null) or gms.P_Project_Stage is null then '00' else gms.P_Project_Stage end as pProjectStageOrganization from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Company c4 on c4.C_Id=mn.P_Audit_Unit left join SYS_Company c5 on c5.C_Id=mn.P_Cost_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID left join ( select P_Id, max(P_Project_Stage) as P_Project_Stage from gantt_milestone_statistics group by P_Id ) gms on gms.P_Id=mn.P_Id
left join ( select ar.P_Id, count(*) as archive_count from Archive_File af left join Archive ar on af.Ap_Id = ar.Ap_Id left join SYS_FileAnnex sfa on sfa.file_id = af.Af_Annex_Id
where ar.Ap_State = 1 and af.Af_State = 1 and (sfa.File_MD5_Code is null or latest_md5.max_key is not null) group by ar.P_Id ) ac on ac.P_Id = mn.P_Id
${params.authSql}
where 1=1
and mn.deleted = false and mn.P_Create_Time is not null
order by archiveFileSum ${params.sortType}
order by d.D_Name ${params.sortType}
order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
order by ${params.sortCJDZ}
order by mn.P_Create_Time DESC
limit #{params.start},#{params.size}

