SELECT * FROM ( SELECT 'EC' AS type, ec.ec_id AS id, ec.p_id AS pId, ec.con_id AS conId, p.p_name AS pName, con.con_name AS conName, ec.ec_Name AS pConName, IFNULL(ec.ec_apply_money, 0) AS budgetAmount, ec.ec_state AS state, ec.ec_Content AS remark, ec.ec_Code AS approvalId FROM con_ec ec left join con_contract con on ec.con_id = con.con_id LEFT JOIN pre_project p ON ec.p_id = p.p_id WHERE 1=1
AND ec.p_id = #{params.pId}
AND p.p_name LIKE CONCAT('%', #{params.pName}, '%')
AND ec.con_id = #{params.conId}
AND ec.ec_Code LIKE CONCAT('%', #{params.approvalId}, '%')
AND ec.ec_apply_money LIKE CONCAT('%', #{params.budgetAmount}, '%')
AND ec.ec_Name LIKE CONCAT('%', #{params.pConName}, '%')
AND ec.ec_Data_Separate_Type = #{params.dataSeparateType}
AND ec.ec_state NOT IN (0,3) UNION ALL SELECT 'VF' AS type, vf.vf_id AS id, vf.p_id AS pId, vf.con_id AS conId, p.p_name AS pName, con.con_name AS conName, vf.vf_Location AS pConName, IFNULL(vf.vf_Apply_Money, 0) AS budgetAmount, vf.vf_state AS state, vf.vf_Content AS remark, vf.vf_Code AS approvalId FROM con_visa_fee vf LEFT JOIN pre_project p ON vf.p_id = p.p_id left join con_contract con on vf.con_id = con.con_id WHERE 1=1
AND vf.p_id = #{params.pId}
AND p.p_name LIKE CONCAT('%', #{pName}, '%')
AND vf.con_id = #{params.conId}
AND vf.vf_Code LIKE CONCAT('%', #{params.approvalId}, '%')
AND vf.vf_Apply_Money LIKE CONCAT('%', #{params.budgetAmount}, '%')
AND vf.vf_Location LIKE CONCAT('%', #{params.pConName}, '%')
AND vf.vf_Data_Separate_Type = #{params.dataSeparateType}
AND vf.vf_state NOT IN (0, 3) ) t
WHERE t.type = #{params.type}

